fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, select the Lists application, and on the default 'Lists' (Browse) section click the 'New List' button. In the 'Create New List' dialog, click the 'Entity *' field (placeholder 'Search and select an entity') and type a few letters of an entity name. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Success is that a searchable dropdown appears and narrows to entities matching what you typed, and picking one fills the Entity field. Note that the 'Create' button stays disabled until BOTH a Name and an Entity are provided. Do NOT need to actually create the list — cancel after verifying the picker filters and the Create-button gating.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Typing in the 'Entity *' field opens a dropdown that narrows to matching entities, and selecting one populates the field",
    "The 'Create' button is disabled until both Name and Entity are set (verifiable by observing it enable only after both are filled)",
    "No error messages, blank screens, or crash pages"
  ]
}
